"""Is every top of an index-tight stage generated by a top of the previous stage? (log §34.3z¹⁶⁵)

Exact search (amalg_sat.Enc) for a monotone F with R_{K−1} of heights ≤ K − 1, R_K of heights ≤ K, ⊤ ∉ R_{K+1}, and a
rank-K element z ∈ R_K none of whose fixed-edge parents x ∈ R_{K−1} (F(x, z) = x, i.e. b(z) ≤ x, or a(x) = z) has
rank K − 1. No singleton configuration, no uniqueness. SAT = counterexample (re-checked in Python).
  python3 top_parent.py (sweep P NMAX | closure K M SEED COUNT)
"""
import sys, collections
sys.path.insert(0, '../separation')
from amalg_sat import Enc
from rstages import stages, a_of, b_of
from tight_probe import helpers, lattices

def query(L, z):
    n = L.n; rk = L.rank; K = rk[z]
    if K < 2: return None
    E = Enc(L, K + 1); r = lambda j, x: E.v('r', j, x)
    E.S.add_clause([-r(K + 1, L.top)]); E.S.add_clause([r(K, z)])
    for x in range(n):
        if rk[x] > K: E.S.add_clause([-r(K, x)])
        if rk[x] > K - 1: E.S.add_clause([-r(K - 1, x)])
    for g in range(n):
        if rk[g] == K - 1:
            E.S.add_clause([-E.v('B', z, g), -r(K - 1, g)]); E.S.add_clause([-r(K - 1, g), -E.v('A', g, z)])
    if not E.S.solve(): E.S.delete(); return False
    F = E.decode(); E.S.delete(); st = stages(L, F); inR = lambda x, j: st[x] is not None and st[x] <= j
    assert inR(z, K) and not inR(L.top, K + 1) and all(rk[x] <= K for x in range(n) if inR(x, K)) and all(rk[x] <= K - 1 for x in range(n) if inR(x, K - 1))
    bz = b_of(L, F, z)
    par = ([bz] if inR(bz, K - 1) else []) + [x for x in range(n) if inR(x, K - 1) and a_of(L, F, x) == z]
    assert par and all(rk[x] < K - 1 for x in par)
    return F, par

if __name__ == '__main__':
    C = collections.Counter(); best = None
    for L in lattices(sys.argv[1:]):
        hit = None
        for z in range(L.n):
            if 2 <= L.rank[z] < L.height:
                res = query(L, z)
                if res: hit = (z, res); break
        C['counterexample' if hit else 'none'] += 1
        if hit and (best is None or L.n < best[0].n): best = (L, hit)
    print(f"top_parent: {dict(C)}" + (f"; smallest |L| = {best[0].n}, rank(z) = {best[0].rank[best[1][0]]}, parents' ranks {[best[0].rank[x] for x in best[1][1][1]]}" if best else ''), flush=True)
    if best:
        import json; json.dump(dict(sets=best[0].S, F=best[1][1][0], m=best[1][0]), open(f"top_parent_min{best[0].n}.json", 'w'))
